def get_svg_icon(name: str, color: str = "#cccccc", size: int = 16) -> QIcon:
    raw_svg = _ICONS_SVG.get(name)
    if not raw_svg:
        return QIcon()
    colored = raw_svg.replace('stroke="currentColor"', f'stroke="{color}"').replace('fill="currentColor"', f'fill="{color}"')
    renderer = QSvgRenderer(QByteArray(colored.encode("utf-8")))
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    return QIcon(pixmap)


def get_svg_pixmap(name: str, color: str = "#cccccc", size: int = 16) -> QPixmap:
    raw_svg = _ICONS_SVG.get(name)
    if not raw_svg:
        pixmap = QPixmap(size, size)
        pixmap.fill(Qt.GlobalColor.transparent)
        return pixmap
    colored = raw_svg.replace('stroke="currentColor"', f'stroke="{color}"').replace('fill="currentColor"', f'fill="{color}"')
    renderer = QSvgRenderer(QByteArray(colored.encode("utf-8")))
    pixmap = QPixmap(size, size)
    pixmap.fill(Qt.GlobalColor.transparent)
    painter = QPainter(pixmap)
    renderer.render(painter)
    painter.end()
    return pixmap
